/* vault.h - representation is private to vault.c */
struct vault;                       /* incomplete type: callers cannot name fields */
struct vault *vault_open(const char *path, const struct subject *who);
int vault_read(struct vault *v, const struct subject *who, void *buf, size_t n);

/* vault.c */
int vault_read(struct vault *v, const struct subject *who, void *buf, size_t n) {
    if (!policy_allows(who, v->acl, OP_READ)) { errno = EACCES; return -1; }
    return read(v->fd, buf, n);      /* the descriptor never leaves the vault */
}

