/* the descriptor is the capability: grant access by passing it, not the path */
int fd = open("/vault/secret", O_RDONLY | O_CLOEXEC);   /* EACCES if not allowed */
if (fd < 0) return -1;
/* hand fd to the worker that may read it; across processes use SCM_RIGHTS */
/* untrusted path components: make the open itself the decision */
struct open_how how = { .flags = O_RDONLY,
                        .resolve = RESOLVE_BENEATH | RESOLVE_NO_SYMLINKS };
syscall(SYS_openat2, dirfd, relpath, &how, sizeof how);
